<?php declare(strict_types=1);
$lcText=static fn(string$s,array$v=[]):string=>\Kulturhus\Native\Language\InventoryLifecycleMessages::text($s,$managerLanguageMessages??[],$v);$lcState=$inventoryLifecycleState;$archiveState=$inventory->archiveStatus($itemId);$archiveHistory=$inventory->archiveHistory($itemId);$lcPosted=is_string($_POST['action']??null)?$_POST['action']:'';$lcData=is_array($_POST['data']??null)?$_POST['data']:[];$lcRoute=$lcState['route'];$lcRecovery=$lcRoute+['lifecycle_recheck'=>bin2hex(random_bytes(6))];$lcUrl=static fn(string$op):string=>url($lcRoute+['item_action'=>$op,'lifecycle_request'=>$lcState['keys'][$op]]).'#gegenstand-entfernen';
$lcHeader=static function(string$op)use($lcPosted,$lcState,$item,$itemId):string{$restore=$lcPosted==='inventory-'.$op;return csrf().hidden('action','inventory-'.$op).hidden('target',$itemId).hidden('version',$restore?$_POST['version']:(string)$item[$op==='remove'?'stock_version':'version']).hidden('request_key',$lcState['keys'][$op]).($op==='archive'?hidden('stock_version',$restore?$_POST['stock_version']:(string)$item['stock_version']):'');};
$lcReason=static function(string$caption,string$value)use($lcText):void{ ?><label><?= e($lcText($caption)) ?> *<textarea class="form-control" name="data[reason]" maxlength="1000" rows="3" required><?= e($value) ?></textarea></label><?php };
?>
<section class="card iv-lifecycle" id="gegenstand-entfernen" data-inventory-lifecycle data-item-id="<?= e($itemId) ?>" data-item-version="<?= (int)$item['version'] ?>" data-stock-version="<?= (int)$item['stock_version'] ?>" data-item-active="<?= (int)$item['active'] ?>"><h2><?= e($lcText($item['active']?'Gegenstand entfernen':'Gegenstand wiederherstellen')) ?></h2><p><strong><?= e($item['name']) ?> · <?= e($item['code']) ?></strong></p>
<?php require __DIR__.'/inventory-lifecycle-original.php'; ?>
<h3><?= e($lcText('Aktueller gespeicherter Bestand')) ?></h3><p><?= e($lcText($item['active']?'Der Gegenstand ist aktiv.':'Der Gegenstand ist archiviert. Seine Belege und sein Verlauf bleiben erhalten.')) ?></p><div class="iv-lifecycle-stock"><?php foreach($archiveState['stock']as$stock): ?><article><h3><?= e($stock['location_name']) ?></h3><dl><?php foreach(['shelf'=>'Im Lager','reserved'=>'Davon reserviert','lent'=>'Ausgeliehen','blocked'=>'Gesperrt']as$key=>$caption): ?><div><dt><?= e($lcText($caption)) ?></dt><dd><?= e($stock[$key].' '.$item['unit']) ?></dd></div><?php endforeach ?></dl></article><?php endforeach;if(!$archiveState['stock']): ?><p><?= e($lcText('Für diesen Gegenstand ist kein Lagerbestand erfasst.')) ?></p><?php endif ?></div>
<?php if(!$lcState['blocked']&&$item['active']): ?>
<p><?= e($lcText('Entferne nur die tatsächlich betroffene Anzahl oder archiviere den gesamten geöffneten Eintrag. Inventarnummer, Rechnungen, Einzelpreise und Verlauf bleiben erhalten.')) ?></p>
<?php if($ivWrite&&$item['tracking_mode']==='quantity'&&!$item['cash_account'])require __DIR__.'/inventory-lifecycle-remove.php'; ?>
<h3><?= e($lcText('Gesamten Gegenstand archivieren')) ?></h3>
<?php if($archiveState['blocker']!==''): ?><p role="status"><strong><?= e($lcText('Der Gegenstand kann noch nicht entfernt werden.')) ?></strong> <?= e($lcText($archiveState['blocker'])) ?></p><?php if($item['cash_account']&&$canFinance): ?><a class="btn btn-outline theme-secondary" href="<?= e(url(['view'=>'finance','tab'=>'bank','account'=>$item['cash_account']])) ?>"><?= e($lcText('Handkasse in Bank & Kasse öffnen')) ?></a><?php elseif(!$item['cash_account']&&$inventory->canReadLoans()): ?><a class="btn btn-outline theme-secondary" href="<?= e(url(['view'=>'inventory','tab'=>'loans','state'=>'open'])) ?>"><?= e($lcText('Offene Ausleihen prüfen')) ?></a><?php endif ?>
<?php elseif($ivWrite): ?><form method="post" action="<?= e($lcUrl('archive')) ?>" data-inventory-lifecycle-operation="archive"><?= $lcHeader('archive') ?><p><?= e($lcText('Erst die ausdrückliche Bestätigung entfernt den gesamten angezeigten Lagerbestand dieses Eintrags einschließlich gesperrter Stücke. Für einen Teil verwende „Nur einen Teil entfernen“. Es wird keine Rechnung storniert und keine Zahlung gebucht. Andere Gegenstände derselben Anschaffung bleiben erhalten.')) ?></p><?php $lcReason('Warum wird der Gegenstand entfernt?',$lcPosted==='inventory-archive'?$lcData['reason']:''); ?><label class="check"><input type="checkbox" name="confirmed" value="1" required <?= $lcPosted==='inventory-archive'&&($_POST['confirmed']??null)==='1'?'checked':'' ?>><span><?= e($lcText('Ich habe diesen Gegenstand und seinen Bestand geprüft. Der gesamte geöffnete Gegenstand soll aus dem aktiven Inventar entfernt werden.')) ?></span></label><div class="actions"><button class="btn btn-solid theme-primary"><?= e($lcText('Gegenstand jetzt entfernen')) ?></button><a class="btn btn-outline theme-secondary" href="<?= e(url($lcRecovery)) ?>"><?= e($lcText('Abbrechen')) ?></a></div><?= hidden('inventory_lifecycle_complete','1') ?></form><?php else: ?><p><?= e($lcText('Zum Entfernen sind Inventar-Bearbeitungsrechte erforderlich.')) ?></p><?php endif ?>
<?php elseif(!$lcState['blocked']&&!$item['active']&&$ivWrite): ?><form method="post" action="<?= e($lcUrl('restore')) ?>" data-inventory-lifecycle-operation="restore"><?= $lcHeader('restore') ?><p><?= e($lcText('Wiederherstellen macht den Eintrag erneut sichtbar. Der frühere Bestand und entfernte Stücke werden nicht automatisch zurückgebucht. Wenn Material tatsächlich noch vorhanden ist, erfasse danach einen bewussten Zugang am richtigen Lagerort.')) ?></p><label class="check"><input type="checkbox" name="confirmed" value="1" required <?= $lcPosted==='inventory-restore'&&($_POST['confirmed']??null)==='1'?'checked':'' ?>><span><?= e($lcText('Ich möchte diesen Gegenstand wieder im aktiven Inventar führen. Der Bestand bleibt zunächst 0.')) ?></span></label><div class="actions"><button class="btn btn-solid theme-primary"><?= e($lcText('Gegenstand wiederherstellen')) ?></button><a class="btn btn-outline theme-secondary" href="<?= e(url(['view'=>'inventory','tab'=>'items','status'=>'archived'])) ?>"><?= e($lcText('Archivierte Gegenstände anzeigen')) ?></a></div><?= hidden('inventory_lifecycle_complete','1') ?></form><?php endif ?>
<?php if($archiveHistory): ?><details class="iv-lifecycle-history"><summary><?= e($lcText('Entfernen und Wiederherstellen')) ?></summary><?php foreach($archiveHistory as$event): ?><article><h3><?= e($lcText(\Kulturhus\Verein\Inventory::ACTIONS[$event['action']])) ?></h3><p><?= e((new DateTimeImmutable($event['happened_at']))->setTimezone(new DateTimeZone('Europe/Berlin'))->format('d.m.Y H:i')) ?></p><p><?= e($event['action']==='restore'?$lcText($event['details'][1]['reason']??''):($event['details'][1]['reason']??'')) ?></p><footer><?= e($ivActorNames->label($event['actor_id'],$lcText)) ?></footer></article><?php endforeach ?></details><?php endif ?></section>
